    function setUp() public {
        // Create exploit contract
        exploit = new ReentrancyExploit();

        // Label addresses for clarity
        vm.label(address(exploit), "ExploitContract");
        vm.label(TARGET, "NOMOS_Token");

        // Get token interface
        INOMOS token = INOMOS(TARGET);

